import { Rajdhani } from "next/font/google";
import "./globals.css";

const rajdhaniSans = Rajdhani({
  subsets: ["latin"],
  variable: "--font-primary",
  display: "swap",
});

export const metadata = {
  title: "React Car Shop",
  description: "Найкращий автосалон на Next.js",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body className="{`${rajdhaniSans.variable}`}">{children}</body>
    </html>
  );
}
